// Advances the ball by a time step `dt` (in seconds) and handles bounces off
// the walls and the paddle. Now also handles brick collisions (fixed #1).
// Returns `true` if the ball is lost (exits through the bottom).
export function step(state, dt) {
  const { ball, paddle, bricks } = state;

  // Tunnelling prevention: break the step into smaller pieces if moving too fast.
  const dist = Math.sqrt(ball.vx * ball.vx + ball.vy * ball.vy) * dt;
  const subSteps = Math.ceil(dist / (ball.r * 2));
  const sdt = dt / subSteps;

  for (let i = 0; i < subSteps; i++) {
    ball.x += ball.vx * sdt;
    ball.y += ball.vy * sdt;

    // Wall bounces
    if (ball.x - ball.r < 0) {
      ball.x = ball.r;
      ball.vx = Math.abs(ball.vx);
    } else if (ball.x + ball.r > WIDTH) {
      ball.x = WIDTH - ball.r;
      ball.vx = -Math.abs(ball.vx);
    }

    if (ball.y - ball.r < 0) {
      ball.y = ball.r;
      ball.vy = Math.abs(ball.vy);
    }

    // Paddle bounce
    if (
      ball.vy > 0 &&
      ball.y + ball.r >= paddle.y &&
      ball.y + ball.r <= paddle.y + paddle.h &&
      ball.x >= paddle.x &&
      ball.x <= paddle.x + paddle.w
    ) {
      ball.y = paddle.y - ball.r;
      ball.vy = -Math.abs(ball.vy);
      const hit = (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2);
      ball.vx = ballSpeed(state.level) * 0.6 * hit;
      state.combo = 0;
    }

    // Brick collisions
    for (const brick of bricks) {
      if (!brick.alive) continue;
      if (collides(ball, brick)) {
        // Resolve collision
        const dx1 = (ball.x + ball.r) - brick.x;
        const dx2 = (brick.x + brick.w) - (ball.x - ball.r);
        const dy1 = (ball.y + ball.r) - brick.y;
        const dy2 = (brick.y + brick.h) - (ball.y - ball.r);

        const overlapX = Math.min(dx1, dx2);
        const overlapY = Math.min(dy1, dy2);

        if (overlapX < overlapY) {
          ball.vx = (dx1 < dx2) ? Math.abs(ball.vx) : -Math.abs(ball.vx);
          ball.x = (dx1 < dx2) ? brick.x - ball.r : brick.x + brick.w + ball.r;
        } else if (overlapY < overlapX) {
          ball.vy = (dy1 < dy2) ? Math.abs(ball.vy) : -Math.abs(ball.vy);
          ball.y = (dy1 < dy2) ? brick.y - ball.r : brick.y + brick.h + ball.r;
        } else {
          // Corner hit
          ball.vx = -ball.vx;
          ball.vy = -ball.vy;
          // Push out to a safe distance
          const angle = Math.atan2(ball.y - (brick.y + brick.h / 2), ball.x - (brick.x + brick.w / 2));
          ball.x = brick.x + brick.w / 2 + Math.cos(angle) * (brick.w / 2 + ball.r);
          ball.y = brick.y + brick.h / 2 + Math.sin(angle) * (brick.h / 2 + ball.r);
        }

        brick.alive = false;
        state.combo += 1;
        state.score += scoreForBrick(brick, state.combo);

        // To prevent bouncing off multiple bricks in the same sub-step (neighbours),
        // we break and re-evaluate from the new position.
        break; 
      }
    }
  }

  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

